TYPE STATES : (IDLE, OPENING, CLOSING, FAULT);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state        : STATES := IDLE;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    openRising   : BOOL;
    closeRising  : BOOL;
END_VAR

    openRising  := openBtn AND NOT prevOpenBtn;
    closeRising := closeBtn AND NOT prevCloseBtn;

    CASE state OF
        IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;

            IF openRising AND NOT openLimit THEN
                state := OPENING;
            ELSIF closeRising AND NOT closeLimit THEN
                state := CLOSING;
            END_IF;

        OPENING:
            IF obstacle THEN
                motorUp   := FALSE;
                motorDown := FALSE;
                errorFlag := TRUE;
                state := FAULT;
            ELSE
                motorUp   := TRUE;
                motorDown := FALSE;
                IF openLimit THEN
                    motorUp   := FALSE;
                    motorDown := FALSE;
                    state := IDLE;
                END_IF;
            END_IF;

        CLOSING:
            IF obstacle THEN
                motorUp   := TRUE;
                motorDown := FALSE;
                state := OPENING;
            ELSE
                motorUp   := FALSE;
                motorDown := TRUE;
                IF closeLimit THEN
                    motorUp   := FALSE;
                    motorDown := FALSE;
                    state := IDLE;
                END_IF;
            END_IF;

        FAULT:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;

            IF openRising AND closeRising AND NOT obstacle THEN
                state := IDLE;
                errorFlag := FALSE;
            END_IF;
    END_CASE;

    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;

END_FUNCTION_BLOCK
